const lookup = JSON.parse(fs.readFileSync("scripts/lookup-switches.json", "utf8"));

const buyingCriteriaDefault = [
  { criterion: "Port count is a headroom decision, not a current-need one", explanation: "Buy for what you'll plug in over the next 2-3 years, not just today. An 8-port switch that's already full the day it arrives means buying a second switch and daisy-chaining, which adds a hop of latency and another point of failure." },
  { criterion: "PoE budget is a shared pool, not per-port", explanation: "A switch rated for 8 PoE+ ports at 120W total does not mean every port gets 30W simultaneously. Add up the real draw of every camera, AP, and phone you'll connect, and make sure the total budget clears it with room to spare." },
  { criterion: "Managed vs unmanaged changes what you can diagnose later", explanation: "An unmanaged switch is zero-configuration but gives you no visibility when something goes wrong. A smart-managed switch adds VLANs, port mirroring, and traffic monitoring for a modest price increase, worth it the first time you need to isolate a misbehaving device." },
  { criterion: "Fanless does not always mean silent under load", explanation: "Most desktop switches are genuinely fanless and silent, but high-port-count PoE switches sometimes add active cooling once the power budget climbs past 200-300W. Check for a fan explicitly if a quiet office or bedroom install matters." },
  { criterion: "Multi-gig speed needs matching cable and network gear", explanation: "A 2.5G or 10G switch only delivers those speeds if your cabling is Cat5e or better (Cat6a for 10G) and the devices on both ends actually support that speed. Mixing a multi-gig switch into an all-Gigabit network gets you nothing extra." },
  { criterion: "Renewed enterprise gear needs a licensing check first", explanation: "Cisco Meraki, Juniper, and some Aruba/HPE switches on Amazon are frequently sold as renewed hardware without an active license or support contract. Confirm what functions before assuming a discounted enterprise switch works like a new one out of the box." },
];

const howWeEvaluatedDefault = [
  { title: "Port Count & Speed Tier", description: "Verified the actual port count, Gigabit vs multi-gig speed rating, and whether every port runs at the advertised speed or only some do, since several switches mix full-speed and lower-speed ports." },
  { title: "PoE Power Budget", description: "Checked the total PoE wattage budget against realistic device counts, not just the per-port maximum, since a switch's total power pool is what actually limits how many cameras or access points it can run." },
  { title: "Management Depth", description: "Classified each switch as unmanaged, smart/easy-managed, or fully managed Layer 2/3, since this determines what troubleshooting and segmentation options are available after installation, not just at setup." },
  { title: "Build & Mounting Flexibility", description: "Weighed fanless vs active cooling, metal vs plastic housing, and desktop/wall/rack mounting options against the switch's likely install environment." },
  { title: "Real-World Documentation Honesty", description: "Favored listings that clearly state cabling requirements, host port requirements, and speed caveats over ones that only advertise the theoretical maximum." },
];

function badge(i, total) {
  if (i === 0) return "Best Overall";
  if (i === total - 1 && total > 2) return "Budget Pick";
  return ["Runner-Up", "Also Great", "Strong Alternative", "Worth Considering", "Solid Option", "Another Pick"][Math.min(i - 1, 5)];
}

function pick(asin, badgeText) {
  const meta = lookup[asin];
  const info = P[asin];
  if (!meta || !info) return null;
  return {
    asin, badge: badgeText,
    name: info.name,
    price: meta.price || "Check price",
    rating: meta.rating,
    reviews: meta.reviewCount,
    imageUrl: meta.image,
    amazonUrl: `https://www.amazon.com/dp/${asin}?tag=theofficejournal-20`,
    description: info.p1 + "\n\n" + info.p2,
    specs: info.specs,
    pros: info.pros,
    cons: info.cons || [],
    bestFor: "",
  };
}

